    mime_type: file.mimeType || file.type || '',
    size: file.size || 0,
    base64: file.base64 || ''
  }))
  : [];

if (!rawMessage.trim() && files.length === 0) return;

const assistantId =
  new URLSearchParams(window.location.search)
    .get('assistant_id') || '';

if (!assistantId) return;

const history =
  variables[CONV_HISTORY_UUID] || [];

const userProfile =
  variables[PROFILE_UUID]?.[0] || {};

const userId = userProfile.id;

const message =
  rawMessage.trim() ||
  'Analyse les fichiers joints et réponds selon les instructions de cet assistant.';

const loadingText =
  userProfile.langue === 'de'
    ? 'Antwort wird vorbereitet…'
    : userProfile.langue === 'en'
      ? 'Preparing the response…'
      : 'Préparation de la réponse…';

let currentHistory = [
  ...history,
  {
    role: 'user',
    content: message
  },
  {
    role: 'assistant',
    content: loadingText
  }
];

wwLib.wwVariable.updateValue(CHAT_LOADING_UUID, true);
wwLib.wwVariable.updateValue(CHAT_STREAMING_UUID, true);

wwLib.wwVariable.updateValue(
  CONV_HISTORY_UUID,
  currentHistory
);

try {
  const response = await fetch(
    `${SUPABASE_URL}/functions/v1/chat-ai`,
    {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify({
        assistant_id: assistantId,
        message,
        history,
        user_id: userId,
        stream: true,
        ...(files.length > 0 ? { files } : {})
      })
    }
  );

  if (!response.ok) {
    const errorText = await response.text();

    currentHistory[currentHistory.length - 1] = {
      role: 'assistant',
      content: errorText ||
        'La réponse IA n’a pas pu être générée.'
    };

    wwLib.wwVariable.updateValue(
      CONV_HISTORY_UUID,
      currentHistory
    );

    return;
  }

  if (!response.body) {
    throw new Error('Flux de réponse indisponible.');
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();

  let assistantContent = '';
  let buffer = '';

  const processLine = (line) => {
    if (!line.startsWith('data: ')) return;

    try {
      const parsed = JSON.parse(line.slice(6).trim());

      if (!parsed.delta) return;

      assistantContent += parsed.delta;

      const updated = [...currentHistory];

      updated[updated.length - 1] = {
        role: 'assistant',
        content: assistantContent.replace(
          /<img[^>]*src=["']([^"']+)["'][^>]*>/gi,
          '![]($1)'
        )
      };

      currentHistory = updated;

      wwLib.wwVariable.updateValue(
        CONV_HISTORY_UUID,
        updated
      );
    } catch { }
  };

  while (true) {
    const { done, value } = await reader.read();

    if (done) break;

    buffer += decoder.decode(value, {
      stream: true
    });

    const lines = buffer.split('\n');
    buffer = lines.pop() || '';

    for (const line of lines) {
      processLine(line);
    }
  }

  buffer += decoder.decode();

  if (buffer.trim()) {
    processLine(buffer.trim());
  }

} catch (error) {
  currentHistory[currentHistory.length - 1] = {
    role: 'assistant',
    content: `Erreur technique : ${error?.message || 'la requête a échoué.'
      }`
  };

  wwLib.wwVariable.updateValue(
    CONV_HISTORY_UUID,
    currentHistory
  );

} finally {
  wwLib.wwVariable.updateValue(CHAT_LOADING_UUID, false);
  wwLib.wwVariable.updateValue(CHAT_STREAMING_UUID, false);
  wwLib.wwVariable.updateValue(FILES_UUID, []);
}

