const escapeHtml = value => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const renderInline = value => {
  let result = escapeHtml(value);
  const codeParts = [];

  result = result.replace(/`([^`]+)`/g, (_, code) => {
    const token = `@@CODE${codeParts.length}@@`;
    codeParts.push('<code style="font-family:Consolas,monospace;background:#f1f1f1;padding:2px 4px;">' + code + '</code>');
    return token;
  });

  result = result.replace(
    /\[([^\]]+)\]\((https?:\/\/[^\s)]+|mailto:[^\s)]+)\)/g,
    '<a href="$2" style="color:#2563eb;text-decoration:underline;">$1</a>'
  );
  result = result.replace(/\*\*(.+?)\*\*|__(.+?)__/g, '<strong>$1$2</strong>');
  result = result.replace(/\*(.+?)\*|_(.+?)_/g, '<em>$1$2</em>');
  result = result.replace(/~~(.+?)~~/g, '<del>$1</del>');

  codeParts.forEach((html, index) => {
    result = result.replace(`@@CODE${index}@@`, html);
  });

  return result;
};

const isTableSeparator = line =>
  /^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)+\|?\s*$/.test(line);

const splitTableRow = line =>
  line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(cell => cell.trim());

const isListLine = line => /^\s*([-*+]|\d+\.)\s+/.test(line);
const isBlockStart = line =>
  /^#{1,6}\s/.test(line) ||
  /^```/.test(line) ||
  /^\s*>/.test(line) ||
  isListLine(line) ||
  /^\s*([-*_]\s*){3,}$/.test(line);

const markdownToHtml = markdown => {
  const lines = markdown.replace(/\r/g, '').split('\n');
  const output = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    if (!line.trim()) {
      i++;
      continue;
    }

    if (/^```/.test(line)) {
      i++;
      const codeLines = [];
      while (i < lines.length && !/^```/.test(lines[i])) {
        codeLines.push(lines[i]);
        i++;
      }
      if (i < lines.length) i++;
      output.push(
        '<pre style="font-family:Consolas,monospace;background:#f4f4f5;padding:12px;white-space:pre-wrap;">' +
        escapeHtml(codeLines.join('\n')) +
        '</pre>'
      );
      continue;
    }

    if (i + 1 < lines.length && line.includes('|') && isTableSeparator(lines[i + 1])) {
      const headers = splitTableRow(line);
      i += 2;
      const rows = [];

      while (i < lines.length && lines[i].includes('|') && lines[i].trim()) {
        rows.push(splitTableRow(lines[i]));
        i++;
      }

      output.push(
        '<table style="border-collapse:collapse;margin:12px 0;">' +
        '<thead><tr>' +
        headers.map(cell => '<th style="border:1px solid #ccc;padding:6px;text-align:left;">' + renderInline(cell) + '</th>').join('') +
        '</tr></thead><tbody>' +
        rows.map(row =>
          '<tr>' + row.map(cell => '<td style="border:1px solid #ccc;padding:6px;">' + renderInline(cell) + '</td>').join('') + '</tr>'
        ).join('') +
        '</tbody></table>'
      );
      continue;
    }

    const heading = line.match(/^(#{1,6})\s+(.+)$/);
    if (heading) {
      const level = heading[1].length;
      output.push(
        `<h${level} style="font-family:Arial,sans-serif;margin:16px 0 8px;">` +
        renderInline(heading[2]) +
        `</h${level}>`
      );
      i++;
      continue;
    }

    if (/^\s*([-*_]\s*){3,}$/.test(line)) {
      output.push('<hr style="border:0;border-top:1px solid #ccc;margin:16px 0;">');
      i++;
      continue;
    }

    if (/^\s*>/.test(line)) {
      const quoteLines = [];
      while (i < lines.length && /^\s*>/.test(lines[i])) {
        quoteLines.push(lines[i].replace(/^\s*>\s?/, ''));
        i++;
      }
      output.push(
        '<blockquote style="border-left:3px solid #ccc;margin:12px 0;padding:4px 12px;color:#555;">' +
        quoteLines.map(text => '<p>' + renderInline(text) + '</p>').join('') +
        '</blockquote>'
      );
      continue;
    }

    if (isListLine(line)) {
      const ordered = /^\s*\d+\./.test(line);
      const tag = ordered ? 'ol' : 'ul';
      const items = [];

      while (i < lines.length && isListLine(lines[i])) {
        items.push(lines[i].replace(/^\s*([-*+]|\d+\.)\s+/, ''));
        i++;
      }

      output.push(
        `<${tag} style="margin:8px 0;padding-left:28px;">` +
        items.map(item => '<li style="margin:4px 0;">' + renderInline(item) + '</li>').join('') +
        `</${tag}>`
      );
      continue;
    }

    const paragraph = [line.trim()];
    i++;

    while (i < lines.length && lines[i].trim() && !isBlockStart(lines[i])) {
      paragraph.push(lines[i].trim());
      i++;
    }

    output.push(
      '<p style="font-family:Arial,sans-serif;font-size:11pt;line-height:1.5;margin:0 0 10px;">' +
      paragraph.map(renderInline).join('<br>') +
      '</p>'
    );
  }

  return '<div style="font-family:Arial,sans-serif;font-size:11pt;line-height:1.5;">' +
    output.join('') +
    '</div>';
};

