const isRecording =
  window._mediaRecorder &&
  window._mediaRecorder.state === 'recording'

if (isRecording) {
  window._mediaRecorder.stop()
} else {
  const stream = await navigator.mediaDevices.getUserMedia({ audio: true })
  const mediaRecorder = new MediaRecorder(stream)

  window._mediaRecorder = mediaRecorder
  window._audioChunks = []

  mediaRecorder.ondataavailable = (e) => {
    window._audioChunks.push(e.data)
  }

  mediaRecorder.onstop = async () => {
    const audioBlob = new Blob(window._audioChunks, {
      type: 'audio/webm',
    })

    const arrayBuffer = await audioBlob.arrayBuffer()
    const bytes = new Uint8Array(arrayBuffer)

    let binary = ''
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i])
    }

    const base64 = btoa(binary)

    const res = await fetch(
      'https://msrsidkrdyzdeatvlgya.supabase.co/functions/v1/whisper-transcribe',
      {
        method: 'POST',
        headers: {
          Authorization: 'Bearer REMPLACE_PAR_TA_CLÉ_ACTUELLE',
          apikey: 'REMPLACE_PAR_TA_CLÉ_ACTUELLE',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ audio: base64 }),
      }
    )

    const data = await res.json()

    wwLib.wwVariable.updateValue(
      'e78dde43-d9b2-4c8a-be4e-9978f0bca57f',
      false
    )

    if (data.transcript) {
      setTimeout(() => {
        const textarea = document.querySelector('#ai-chat textarea')

        if (!textarea) return

        const valueSetter = Object.getOwnPropertyDescriptor(
          HTMLTextAreaElement.prototype,
          'value'
        ).set

        valueSetter.call(textarea, data.transcript)

        textarea.dispatchEvent(
          new Event('input', {
            bubbles: true,
          })
        )

        textarea.dispatchEvent(
          new Event('change', {
            bubbles: true,
          })
        )

        textarea.focus()
      }, 100)
    }

    stream.getTracks().forEach((track) => track.stop())
  }

  wwLib.wwVariable.updateValue(
    'e78dde43-d9b2-4c8a-be4e-9978f0bca57f',
    true
  )

  mediaRecorder.start()
}

